let LASTCH=0;
/* ---------- planets & South Indian chart ---------- */
const BODY={Su:'Sun',Mo:'Moon',Ma:'Mars',Me:'Mercury',Ju:'Jupiter',Ve:'Venus',Sa:'Saturn'};
const CODES=['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'];
const MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
