    if(st.gT)add(-16,'Tithi gandanta (junction of tithis)','திதி கண்டாந்தம்','h'); if(st.gN)add(-16,'Nakshatra gandanta (junction of stars)','நட்சத்திர கண்டாந்தம்','h');
