    if(AMRITA[wd]===st.nk)add(8,'Amrita Siddha yoga: '+WDN[wd]+' with '+nkn,'அமிர்த சித்த யோகம்: '+WDT[wd]+' + '+nkt);
    if(st.nk===7)add(4,'Pushya has the power to neutralise faults','புஷ்யம் தோஷங்களை நீக்கும் வலிமை உடையது');
