    if(X.kalam){ if(st.rk)add(-30,'Rahu kalam','ராகு காலம்','h'); if(st.ym)add(-26,'Yamagandam','எமகண்டம்','h'); if(st.gk)add(-20,'Gulika kalam','குளிகை காலம்','h'); if(st.dm)add(-24,'Durmuhurta','துர்முகூர்த்தம்','h'); }
