    const ben=['Ju','Ve','Me'].filter(c=>[1,4,7,10,5,9].indexOf(hs(c))>=0); if(ben.length)add(4*ben.length,'Benefics in kendra or trikona: '+ben.map(c=>NAME[c]).join(', '),'கேந்திர, கோணத்தில் சுப கிரகங்கள்: '+ben.map(c=>TA[c]).join(', '));
    if(['Ju','Ve'].some(c=>hs(c)===1))add(4,'Jupiter or Venus is in the rising sign','குரு அல்லது சுக்கிரன் லக்னத்தில்');
    const bad2=['Su','Ma','Sa','Ra','Ke'].some(c=>hs(c)===2), bad12=['Su','Ma','Sa','Ra','Ke'].some(c=>hs(c)===12); if(bad2&&bad12)add(-10,'Karthari dosha: malefics on both sides of the rising sign','கர்த்தரி தோஷம்: லக்னத்தின் இருபுறமும் பாவ கிரகங்கள்');
    if(CODES.some(c=>c!=='Mo'&&Math.floor(pl[c]/30)===Math.floor(pl.Mo/30)))add(P.sag?-8:-2,'The Moon is with another planet (Sagraha Chandra)','சந்திரன் வேறு கிரகத்துடன் (சகிரக சந்திரன்)');
    if(P.lag){ if(P.lag.indexOf(lg)>=0)add(5,'The rising sign '+SIGNS[lg][0]+' suits this work','லக்னம் '+TSIGN[lg]+' இந்த காரியத்துக்கு ஏற்றது'); else add(-3,'The rising sign '+SIGNS[lg][0]+' is not among the best for this work','லக்னம் '+TSIGN[lg]+' சிறந்தது அல்ல'); }
    X.persons.forEach(p=>{ if(p.lagna!=null&&P.ashtama&&lg===(p.lagna+7)%12)add(-25,p.name+': the rising sign is the 8th from the birth ascendant (Ashtama lagna)',p.name+': லக்னம் பிறப்பு லக்னத்திலிருந்து 8-ஆம் இடம் (அஷ்டம லக்னம்)','h'); else if(p.lagna!=null&&lg===(p.lagna+7)%12)add(-12,p.name+': the rising sign is the 8th from the birth ascendant',p.name+': லக்னம் பிறப்பு லக்னத்திலிருந்து 8-ஆம் இடம்');
      if(p.indu!=null&&P.indu||(p.indu!=null&&(P.id==='business'||P.id==='general'))){ const m=st.ms; if([0,4,8,10].some(o=>(p.indu+o)%12===m))add(6,p.name+': the Moon is in or trine to the Indu Lagna (wealth point)',p.name+': சந்திரன் இந்து லக்னம் அல்லது அதன் கோணத்தில் (செல்வப் புள்ளி)'); } });

