    if(D.kp){ const r=D.kp.find(q=>t>=q.s&&t<q.e); if(r)add(10+(r.x.high?6:0)+(r.x.money?3:0),'KP Chandra muhurtham rule is met (the Moon’s star owner is the '+(NAME[r.x.ms])+', a gain lord of this rising sign)','KP சந்திர முகூர்த்த விதி நிறைவு (சந்திரனின் நட்சத்திர அதிபதி '+TA[r.x.ms]+', இந்த லக்னத்தின் லாப அதிபதி)'); }
