      [[4,3,'4th lord (home)','4-ஆம் அதிபதி (வீடு)'],[9,3,'9th lord (fortune)','9-ஆம் அதிபதி (பாக்கியம்)'],[2,2,'2nd lord (wealth)','2-ஆம் அதிபதி (செல்வம்)'],[11,2,'11th lord (gains)','11-ஆம் அதிபதி (லாபம்)'],[1,2,'ascendant lord','லக்னாதிபதி'],[5,1.5,'5th lord (merit)','5-ஆம் அதிபதி (புண்ணியம்)']].forEach(a=>addR(lordOf(a[0]),a[1],a[2],a[3]));
      addR('Mo',1.5,'the Moon (mind, home)','சந்திரன் (மனம், இல்லம்)'); addR('Ve',1.5,'Venus (comforts)','சுக்கிரன் (சுகம்)'); addR('Ju',1.5,'Jupiter (blessing)','குரு (அருள்)'); addR('Ma',1,'Mars (land)','செவ்வாய் (நிலம்)'); addR('Sa',.5,'Saturn (permanence)','சனி (நிலைப்பு)');
      ['Ra','Ke'].forEach(c=>{ if([1,2,4,5,9,10,11].indexOf(house(c))>=0)addR(c,.8,'placed in a good house','நல்ல வீட்டில் அமர்வு'); });
      const rank=Object.keys(role).map(c=>({c:c,sc:role[c].w+.8*ps(c),ps:ps(c),roles:role[c].r})).sort((a,b)=>b.sc-a.sc);
