    pick('hsPickB','hsPickBH',p=>{ g('hsBlat').value=(+p.lat).toFixed(4); g('hsBlon').value=(+p.lon).toFixed(4); if(p.tz!=null&&p.tz!=='')g('hsBtz').value=p.tz; g('hsMsg').className='msg'; g('hsMsg').textContent='Birth place set: '+(p.name||''); });
