    if(X.moonNak&&n===X.moonNak){ s+=1.2; why.push(['your birth star number','உங்கள் ஜன்ம நட்சத்திர எண்']); }
    if(X.drawD&&(n===X.drawD||red(n)===red(X.drawD))&&n<=31){ s+=0.8; if(n===X.drawD)why.push(['the draw date','குலுக்கல் தேதி']); }
    const G=[], B=[]; if(G.indexOf(n)>=0){ s+=0.8; why.push(['a fortunate compound number','அதிர்ஷ்ட கூட்டு எண்']); } if(B.indexOf(n)>=0){ s-=1.6; }
    return {s:s,why:why,p:p};
