function bpDateStr(){const y=+$('bpYear').value,m=+$('bpMonth').value,d=+$('bpDay').value; if(!y||!m||!d)return ''; const t=new Date(Date.UTC(y,m-1,d)); if(t.getUTCDate()!==d||t.getUTCMonth()!==m-1)return ''; return y+'-'+p2(m)+'-'+p2(d);}
