      const rise=Astronomy.SearchRiseSet(Astronomy.Body.Sun,obs,+1,Astronomy.MakeTime(new Date(loc0)),1), set=Astronomy.SearchRiseSet(Astronomy.Body.Sun,obs,-1,Astronomy.MakeTime(new Date(loc0)),1);
