    const l=STBY[cn]||[]; el.innerHTML='<option value="*s">All states ('+l.filter(Boolean).length+')</option>'+l.map(n=>'<option value="'+ftE(n)+'">'+ftE(n||'(state not listed)')+'</option>').join('');
