      const tx='Guru Agasthiya Muhurtham '+M.f+' to '+M.t+' ('+M.lat+', '+M.lon+', '+M.tzs+')\n'+L.map(w=>{ const off=M.tzf(w.s), g=w.ev.seg; return fmtDate(w.s,off)+'  '+hms(w.s,off)+' – '+hms(w.e,off)+'  '+G.GR[G.rank(w.ev)][0]+' '+w.ev.marks+' marks  '+SIGNS[g.sign][0]+' ascendant  '+NAME[g.lord]+'/'+NAME[g.star]+'/'+NAME[g.sub]; }).join('\n');
