        const e=good?'water in plenty and good water':n<=2?'sorrow':n>=23?'dry pond, loss of water':[15,16].indexOf(n)>=0?'polluted water':'no water';
        const t=good?'நீர் மிகுதி, நல்ல நீர்':n<=2?'துயரம்':n>=23?'குளம் வற்றும், நீர் இழப்பு':[15,16].indexOf(n)>=0?'கெட்ட நீர்':'நீர் இல்லை';
