      if(V.sank){ const ok=f.sunDeg>=1&&f.sunDeg<=29; add('sank',ok,true,0,ok?tr('Not a Sankranti day','சங்கிராந்தி நாள் அல்ல'):tr('Sankranti (Sun changes sign) – work started now does not succeed','சங்கிராந்தி (சூரியன் ராசி மாறும் நேரம்) – இப்போது தொடங்கும் வேலை வெற்றி பெறாது')); }
      if(V.ambu){ const ok=!(f.sunLon>=66.667&&f.sunLon<=69.667); add('ambu',ok,true,0,ok?tr('Not in the Ardra days when the Earth is resting','பூமி ஓய்வு நாட்கள் (ஆருத்ரா) அல்ல'):tr('Earth’s resting days (Sun in Ardra, 6°40′–9°40′ Gemini) – no sowing','பூமி ஓய்வு நாட்கள் (சூரியன் திருவாதிரையில், மிதுனம் 6°40′–9°40′) – விதைக்க வேண்டாம்')); }
