    for(let i=0;i<pool.length;i++){ const r=pool[i]; if(cats&&cats.indexOf(r.c)<0)continue; if(!genderOk(r,o.gender||'any'))continue; if(o.letter&&r.n.charAt(0).toUpperCase()!==o.letter)continue; if(q&&r.n.toLowerCase().indexOf(q)<0&&(r.m||'').toLowerCase().indexOf(q)<0&&r.ta.indexOf(q)<0)continue; total++; if(res.length<o.max)res.push(r); }
