  /* ---------- v10.15: more rules (lucky name totals, letters and planets, Lo Shu, years, business, partners) ---------- */
  const LUCKYNAME={1:[1],2:[2,7],3:[3,9],4:[1],5:[1,2,3,4,5,6,7,8,9],6:[6,9],7:[2,7,9],8:[5],9:[3,6,9]};
