  const PLANES=[['Mental plane',[4,9,2]],['Emotional plane',[3,5,7]],['Practical plane',[8,1,6]],['Thought plane',[4,3,8]],['Will plane',[9,5,1]],['Action plane',[2,7,6]],['Success plane',[4,5,6]],['Determination plane',[2,5,8]]];
