  const MISS=window.__mnMiss=window.__mnMiss||{};
  const tr=(s,lg)=>{ if(lg==='en'||lg==='bi')return s; const p=PACK()[lg]; if(p&&p[s])return p[s]; MISS[s]=1; return s; };
