    opt('nmMode',MODES.map(x=>MODEN[x])); opt('nmBt',N.BIZ.map(b=>b[1])); opt('nmGen',['Male','Female']); opt('nmGen1',['Boy','Girl']); opt('nmGen2',['Boy','Girl']); opt('nmBab',['One baby','Twins']); opt('nmPur',GOALS.map(g=>GOALN[g])); opt('nmTwo',['No','Yes']); opt('nmStar',['Yes','No']); opt('nmGenD',['Any','Boy','Girl']);
