    const hv=hlord(ch,5)==='Ve'; let vh=0; if(hv&&phouse(ch,'Ve')===11&&psign(ch,'Ve')===psign(ch,l6)){ vh=2; add(1,'5th lord is Venus, in the 11th with the 6th lord: a large win in horse racing','5-ஆம் அதிபதி சுக்கிரன் 11-ல் 6-ஆம் அதிபதியுடன்: குதிரைப் பந்தய வெற்றி'); } else if(hv&&phouse(ch,'Ve')===12&&psign(ch,'Ve')===psign(ch,l6)){ vh=-2; add(-1,'5th lord Venus with the 6th lord in the 12th: heavy loss in horse racing','5-ஆம் அதிபதி சுக்கிரன் 6-ஆம் அதிபதியுடன் 12-ல்: பெரு நஷ்டம்'); }
    const rh=phouse(ch,'Ra'); const rfr=['Ve','Sa','Me',l5,hlord(ch,9),l11].indexOf(SL[psign(ch,'Ra')])>=0||[l5,hlord(ch,9),l11].some(p=>psign(ch,p)===psign(ch,'Ra'));
    if([5,9,11].indexOf(rh)>=0){ add(rfr?1:0,'Rahu in the '+rh+'th house'+(rfr?' with a friendly lord: enough money through speculation':''),'ராகு '+rh+'-ல்'+(rfr?' நட்பு அதிபதியுடன்: ஊக வணிகப் பணம்':'')); }
    const mal10=in5.length>=0&&CODES.filter(p=>phouse(ch,p)===10&&['Sa','Ma','Ra','Ke'].indexOf(p)>=0);
    if(mal10.length)add(1,'A malefic ('+mal10.map(PN).join(', ')+') in the 10th house: a strong liking for gambling (a liking, not a promise)','10-ல் பாப கிரகம் ('+mal10.map(p=>TA[p]).join(', ')+'): சூதாட்டத்தில் ஆர்வம்');
    const bulk=['Ju','Ve'].map(p=>({p:p,n:inter(sig(ch,p),[2,5,7,8,11]).length,b:sig(ch,p).indexOf(12)>=0}));
    bulk.forEach(x=>{ if(x.n>=2&&!x.b)add(1,PN(x.p)+' signifies '+inter(sig(ch,x.p),[2,5,7,8,11]).join(', ')+': can bring a bulk amount','குறிக்கும் '+inter(sig(ch,x.p),[2,5,7,8,11]).join(', ')+': பெரும் தொகை வாய்ப்பு'); });
    const pan=[2,5,8,11].filter(fav);
    add(pan.length>=3?1:pan.length>=2?0:-1,'Money houses 2, 5, 8, 11 with a favourable sub lord: '+(pan.join(', ')||'none'),'2, 5, 8, 11 பாவங்களில் சாதக உப அதிபதி: '+(pan.join(', ')||'இல்லை'));
    // scores
