    let inv=30+10*ic2+10*ic11-(bad(2)?12:0)-(bad(11)?12:0)+((cls(ch,'Ju')==='P'||cls(ch,'Ju')==='p')?6:0)+((cls(ch,'Sa')==='P'||cls(ch,'Sa')==='p')?6:0);
    inv=clamp(inv);
