  cs.addEventListener('change',()=>{states();fill();}); $('ntState').addEventListener('change',fill); $('ntSearch').addEventListener('input',fill); $('ntCity').addEventListener('change',pick); $('ntTz').addEventListener('input',off);
  states(); fill();
