  $('ntMpList').addEventListener('click',e=>{ const b=e.target.closest('button[data-i]'); if(!b)return; const a=mpList(), p=a.splice(+b.dataset.i,1)[0]; try{ localStorage.setItem('ga_myplaces',JSON.stringify(a)); }catch(x){} if(p){ const k=WC.findIndex(w=>w.n===p.n&&w.lat===p.lat&&w.lon===p.lon); if(k>=0)WC.splice(k,1); const l=WCBY[p.cc]; if(l){ const j=l.findIndex(w=>w.n===p.n&&w.lat===p.lat); if(j>=0)l.splice(j,1); } } mpDraw(); });
