    const av=CODES.filter(p=>N.cls(ch,p)==='A'&&N.KAR[p]).slice(0,3);
    if(av.length)h+='<div class="lf-item info">'+bl('Be careful with','கவனம்')+': '+av.map(p=>N.PN(p)+' ('+N.KAR[p][0].split(',')[0]+')').join('; ')+'</div>';
    // lucky numbers
    const lk=R.lk;
    h+=SEC('Lucky numbers and week days','அதிர்ஷ்ட எண்கள், கிழமைகள்')+'<div class="lf-item info">'+bl('Numbers','எண்கள்')+': <b>'+lk.set.join(', ')+'</b> ('+bl('birth date root','பிறந்த தேதி எண்')+' '+lk.dn+', '+bl('Sun-sign ruler number','ராசி அதிபதி எண்')+' '+lk.sn+')<br>'+bl('Week days','கிழமைகள்')+': <b>'+lk.days.map(i=>N.WKN[i]+' · '+N.WKT[i]).join(', ')+'</b></div>';
    // dasha periods
    const good=R.per.filter(p=>p.g[2]==='yes').slice(0,12), cur=R.per.find(p=>p.s<=Date.now()&&p.e>Date.now()), bad=R.per.filter(p=>p.g[2]==='no').slice(0,6);
    h+=SEC('Lucky and unlucky periods of life (next 12 years)','வாழ்க்கையில் அதிர்ஷ்ட / சோதனை காலங்கள்');
    if(cur)h+='<div class="lf-item info"><b>'+bl('Running now','நடப்பு')+'</b>: '+N.PN(cur.md)+' / '+N.PN(cur.ad)+' · '+fmtDate(cur.s,off)+' → '+fmtDate(cur.e,off)+' '+pill(cur.g)+'</div>';
    const prow=p=>'<div class="ntr '+(p.g[2]==='yes'?'y':p.g[2]==='no'?'n':'m')+'"><b>'+N.PN(p.md)+' / '+N.PN(p.ad)+'</b> '+fmtDate(p.s,off)+' → '+fmtDate(p.e,off)+' ('+dur(p.e-p.s)+') '+pill(p.g)+'</div>';
    h+='<div class="ntrules">'+(good.length?good.map(prow).join(''):'<div class="ntr m">'+bi('No strongly lucky period in this span.','இந்த காலத்தில் வலுவான அதிர்ஷ்ட காலம் இல்லை.')+'</div>')+(bad.length?'<div class="ntr m"><b>'+bi('Periods to trade very lightly','மிகக் குறைவாக வர்த்தகம் செய்ய வேண்டிய காலம்')+'</b></div>'+bad.map(prow).join(''):'')+'</div>';
    // favourable days
