  $('ntBtn').addEventListener('click',()=>{ const pn=$('ntPanel'); pn.classList.remove('hide'); if(!pn.dataset.o){ pn.dataset.o=1; $('ntLat').value=$('lat').value; $('ntLon').value=$('lon').value; $('ntTz').value=PL_TZ||$('tz').value; $('ntTzT').value=PL_TZ||$('tz').value; off(); } pn.scrollIntoView({block:'start'}); });
