  const KAR={job:['Sa','Su'],promo:['Su'],business:['Me'],busgain:['Me','Ju'],partner:['Me'],share:['Me','Ju'],politic:['Su','Ju'],edu:['Me','Ju'],exam:['Me'],scholar:['Ju'],phd:['Ju','Sa'],abstudy:['Ra','Ju'],fgo:['Ra','Mo'],visa:['Me','Ra'],settle:['Ra','Sa'],wealth:['Ju','Ve'],loan:['Sa'],house:['Ma','Sa'],vehicle:['Ve'],inherit:['Sa'],marry:['Ve','Ju'],love:['Ve'],child:['Ju'],recover:['Su'],
    vitality:['Su'],chronic:['Sa'],fame:['Su'],leader:['Su'],mind:['Mo'],spirit:['Ke','Ju'],danger:['Ma'],earn:['Ju'],bank:['Ju'],jewel:['Ve','Ju'],family:['Ju'],speech:['Me','Ju'],eyerisk:['Su','Mo'],sibling:['Ma'],travel:['Mo'],comm:['Me'],nego:['Me','Ju'],contract:['Me'],courage:['Ma'],interview:['Me'],news:['Me'],pubbook:['Me','Ju'],marketing:['Me'],land:['Ma','Sa'],construct:['Ma','Sa'],luxury:['Ve'],mother:['Mo'],peace:['Mo'],sellprop:['Ma'],kidprog:['Ju'],romance:['Ve'],intel:['Me','Ju'],god:['Ju','Ke'],talent:['Ve'],spec:['Ra','Me'],lottery:['Ju'],sports:['Ma'],enemy:['Ma'],court:['Ju'],govjob:['Su'],illness:['Sa'],helpers:['Sa'],harmony:['Ve'],sep:['Sa'],forspouse:['Ra'],public:['Ve','Me'],clients:['Me'],insurance:['Ju'],surgery:['Ma','Su'],accident:['Ma'],longill:['Sa'],occult:['Ke','Sa'],research:['Sa','Ju'],luck:['Ju','Su'],father:['Su'],guru:['Ju'],teach:['Ju','Me'],pubtech:['Me','Ju'],charity:['Ju'],expbiz:['Ra','Me'],award:['Su','Ju'],desire:['Ju'],friends:['Ju'],election:['Su'],invest:['Ju'],hosp:['Mo','Ke'],loss:['Ke']};
  /* id, house, English, Tamil, cusps read, favourable houses, denying (or protecting) houses, 'r' = a risk topic */
