      // Mars - nodes
      ['Ra','Ke'].forEach(n=>pair(i,'Ma',n,{conj:5,opp:0,sq:0},r=>({eq:0.8+1.2*near(r,5),acc:1+1.5*near(r,5),unrest:0.8+1.2*near(r,5),heat:0.5+0.8*near(r,5)}),'ma'+n,['conj']));
      // Saturn - nodes
      ['Ra','Ke'].forEach(n=>pair(i,'Sa',n,{conj:6,opp:0,sq:0},r=>({health:1+1.5*near(r,6),econ:1+1.5*near(r,6),eq:0.5+0.8*near(r,6),unrest:0.6+0.8*near(r,6)}),'sa'+n,['conj']));
