      // Sun - Mars, Sun - Saturn, Mercury - Rahu/Ketu
      pair(i,'Su','Ma',{conj:10,opp:0,sq:0},r=>({heat:1+1.5*near(r,10),acc:0.6+0.8*near(r,10),unrest:0.4+0.5*near(r,10)}),'sunma',['conj']);
      pair(i,'Su','Sa',{conj:6,opp:6,sq:0},r=>({health:0.8+0.8*near(r,6),econ:0.5+0.6*near(r,6),unrest:0.3}),'susa',['conj','opp']);
      ['Ra','Ke'].forEach(n=>pair(i,'Me',n,{conj:5,opp:0,sq:0},r=>({acc:0.8+1.2*near(r,5),health:0.3,econ:0.3}),'me'+n,['conj']));
      // Jupiter - Venus (benefic rain and plenty)
      { const r=asp(P.Ju,P.Ve); if(r[0]==='conj'&&r[1]<=8)add(i,'juve',{rain:0.8+0.8*near(r[1],8)},'Jupiter and Venus together (orb '+r[1].toFixed(1)+'°) in '+SN(sg(d,'Ju')),'குரு, சுக்கிரன் இணைவு (அளவு '+r[1].toFixed(1)+'°) '+SNT(sg(d,'Ju')),['Ju','Ve']); }
