      if(WATER.indexOf(sg(d,'Ve'))>=0)add(i,'vew',{rain:0.9},'Venus in a water sign ('+SN(sg(d,'Ve'))+')','சுக்கிரன் நீர் ராசியில் ('+SNT(sg(d,'Ve'))+')',['Ve']);
      if(WATER.indexOf(sg(d,'Sa'))>=0)add(i,'saw',{rain:0.9,storm:0.8},'Saturn in a water sign ('+SN(sg(d,'Sa'))+')','சனி நீர் ராசியில் ('+SNT(sg(d,'Sa'))+')',['Sa']);
      if(WATER.indexOf(sg(d,'Ma'))>=0)add(i,'maw',{storm:1,rain:0.4},'Mars in a water sign ('+SN(sg(d,'Ma'))+') stirs storms','செவ்வாய் நீர் ராசியில் ('+SNT(sg(d,'Ma'))+') புயலைத் தூண்டும்',['Ma']);
      if(WATER.indexOf(sg(d,'Me'))>=0)add(i,'mew',{rain:0.5},'Mercury in a water sign ('+SN(sg(d,'Me'))+')','புதன் நீர் ராசியில் ('+SNT(sg(d,'Me'))+')',['Me']);
