      { const m=mod(P.Mo-P.Su); if(m>160&&m<200&&WATER.indexOf(sg(d,'Mo'))>=0)add(i,'mofull',{rain:1,storm:0.7},'Full Moon in a water sign ('+SN(sg(d,'Mo'))+')','முழு நிலவு நீர் ராசியில் ('+SNT(sg(d,'Mo'))+')',['Mo']); }
