  /* ---- windows of strong indication ---- */
  function windows(D,ev,h,thr){
    const N=D.length, sc=ev.map(x=>x.reduce((s,y)=>s+(y.hz[h]||0),0)); const W=[]; let cur=null;
    for(let i=0;i<N;i++){ if(sc[i]>=thr){ if(cur&&i-cur.e<=3){ cur.e=i; } else { cur={s:i,e:i,pk:i}; W.push(cur); } if(sc[i]>sc[cur.pk])cur.pk=i; } }
    W.forEach(w=>{ w.score=sc[w.pk]; });
    return {W:W,sc:sc};
  }
  const fd=(ms,off)=>fmtDate(ms,off), hm=(ms,off)=>{ const d=new Date(ms+off*3600000), p=n=>(n<10?'0':'')+n; return p(d.getUTCHours())+':'+p(d.getUTCMinutes()); };
  const LV=s=>s>=6?['High indication','வலுவான குறிப்பு','ntA']:s>=4?['Elevated','கூடுதல் குறிப்பு','ntA']:['Watch','கவனம்','ntM'];
  function placeRead(ctx,hz,peak,items){
    const off=ctx.tzf(D0[peak].t), dd=new Date(D0[peak].t+off*3600000), ms=Date.UTC(dd.getUTCFullYear(),dd.getUTCMonth(),dd.getUTCDate(),6,0,0)-off*3600000;
    const asc=sgn(sidAsc(ms,ctx.lat,ctx.lon,ctx.kind)), P=D0[peak].P, H=HBY[hz][3];
    const trig=hz==='rain'?['Ju','Ve','Sa','Ma']:['Ma','Sa','Ra','Ke'];
    const hit=trig.filter(c=>H.indexOf(((sgn(P[c])-asc+12)%12)+1)>=0);
    const hs=trig.map(c=>PN(c)+' in house '+(((sgn(P[c])-asc+12)%12)+1)).join(', ');
    const hsT=trig.map(c=>PT(c)+' '+(((sgn(P[c])-asc+12)%12)+1)+'-ஆம் வீடு').join(', ');
    const lvl=hit.length>=2?['Marked stress','தெளிவான அழுத்தம்'] :hit.length===1?['Mild stress','லேசான அழுத்தம்']:['No special stress','சிறப்பு அழுத்தம் இல்லை'];
    return {lvl:lvl,txt:B('Your place (dawn ascendant '+SN(asc)+'): '+hs+'. Sensitive houses for this matter: '+H.join(', ')+'. Reading for your place: '+lvl[0]+'.','உங்கள் இடம் (காலை லக்னம் '+SNT(asc)+'): '+hsT+'. இவ்விஷயத்தின் உணர்திறன் வீடுகள்: '+H.join(', ')+'. உங்கள் இடத்துக்கு: '+lvl[1]+'.'),hit:hit.length};
  }
