  function hqId(t){ const s=t.toLowerCase(); const Q=window.__hqApi&&__hqApi.QB; for(const x of HQ){ if((x[0].test(s)||x[0].test(t))&&(!Q||Q[x[1]]))return x[1]; } return null; }
  const isQuestion=t=>/\?|^\s*(will|shall|can|could|am i|is |are |do i|does|would|should|may i|whether|when will|how long|whom will)|வருமா|கிடைக்குமா|நடக்குமா|ஆகுமா|போவேனா|முடியுமா|இருக்குமா|உண்டா|பாஸ்|ஆவேனா/i.test(t);
  function horary(qid,text){
    const QB=__hqApi.QB, q=QB[qid]; const m=add('b','<p>'+L('Your question is read as: <b>'+ES(q.en)+'</b>','உங்கள் கேள்வி: <b>'+ES(q.ta||q.en)+'</b>')+'</p><p>'+L('For a KP horary answer, think of your question and give a number between 1 and 249, or let me use the exact time of your question.','KP பிரசன்ன விடைக்கு, உங்கள் கேள்வியை நினைத்து 1 முதல் 249 வரை ஒரு எண்ணைக் கொடுங்கள்; அல்லது கேள்வி கேட்கும் இந்த நேரத்தை எடுத்துக்கொள்ளலாம்.')+'</p><div class="ak-row"><input type="number" min="1" max="249" class="ak-in2 ak-hn" placeholder="1 – 249"><button type="button" class="primary ak-hg">'+ES(L('Use this number','இந்த எண்'))+'</button><button type="button" class="ak-hnow">'+ES(L('Use the time now','இப்போதைய நேரம்'))+'</button></div>');
    const go=num=>{ m.querySelectorAll('input,button').forEach(x=>{ x.disabled=true; }); horaryRun(qid,num,text); };
    m.querySelector('.ak-hg').addEventListener('click',()=>{ const n=parseInt(m.querySelector('.ak-hn').value,10); if(!(n>=1&&n<=249)){ m.querySelector('.ak-hn').style.outline='2px solid #c0392b'; return; } go(n); });
    m.querySelector('.ak-hnow').addEventListener('click',()=>go(0));
  }
  function horaryRun(qid,num,text,cb,Pp){
    const P=Pp||curPlace(); if(isNaN(P.lat)||!P.tz){ add('b','<p class="msg err">'+L('Please choose your place first (Location at the top of the app).','முதலில் உங்கள் இடத்தைத் தேர்ந்தெடுங்கள் (செயலியின் மேலே உள்ள இடம்).')+'</p>'); return; }
    const w=add('b','<p>'+L('Casting the horary chart and reading the cusps…','பிரசன்ன ஜாதகத்தைக் கணித்து பாவ முனைகளைப் பார்க்கிறேன்…')+'</p>');
    const ids=['hqQ','hqMode','hqNum','hqWhen','hqLat','hqLon','hqTz','hqAbout'], keep={}; ids.forEach(i=>{ keep[i]=$(i)?$(i).value:''; });
    try{
      $('hqQ').value=qid; $('hqWhen').value='now'; $('hqAbout').value='0';
      const mo=$('hqMode'); if(num){ mo.value='num'; $('hqNum').value=num; } else { const o=[].slice.call(mo.options).find(x=>x.value!=='num'); if(o)mo.value=o.value; }
      $('hqLat').value=P.lat; $('hqLon').value=P.lon; $('hqTz').value=P.tz; window.__hq=null; $('hqGo').click();
    }catch(e){ w.remove(); err(e); return; }
    let n=0; const iv=setInterval(()=>{ n++;
      const done=window.__hq&&window.__hq.res, bad=$('hqMsg')&&/err/.test($('hqMsg').className)&&$('hqMsg').textContent;
      if(done||bad||n>200){ clearInterval(iv); w.remove();
        try{ if(!done){ add('b','<p class="msg err">'+ES(bad||L('The chart could not be finished.','ஜாதகத்தை முடிக்க இயலவில்லை.'))+'</p>'); }
          else { horaryShow(qid,num,text,P,!!cb); } }catch(e){ err(e); }
        ids.forEach(i=>{ try{ if($(i)&&i!=='hqQ')$(i).value=keep[i]; }catch(e){} }); if(cb)setTimeout(cb,40); }
    },200);
  }
  function horaryShow(qid,num,text,P,multi){
    const H=window.__hq, res=H.res, QB=__hqApi.QB, q=QB[qid]; const ev=res.ev;
    const V={YES:['YES – the event is promised','ஆம் – நிகழ்வு உறுதி'],LIKELY:['LIKELY YES – promised, with conditions','பெரும்பாலும் ஆம் – நிபந்தனைகளுடன் உறுதி'],DOUBTFUL:['DOUBTFUL – the promise is weak','சந்தேகம் – வாக்குறுதி பலவீனம்'],NO:['NO – the event is not promised','இல்லை – நிகழ்வு உறுதி இல்லை']}[ev]||[ev,ev];
    const cls=ev==='YES'?'g3':ev==='LIKELY'?'g2':ev==='DOUBTFUL'?'g1':'g0';
    let h='<p><b>'+ES(gm(q.en,q.ta||q.en))+'</b></p><p><span class="ak-pill '+cls+'" style="font-size:15px">'+ES(gm(V[0],V[1]))+'</span></p>';
    h+='<p>'+L('Horary '+(num?'number '+num:'time of the question')+' at '+ES(pname(P))+'. Why:','பிரசன்னம் '+(num?'எண் '+num:'கேள்வி நேரம்')+', இடம் '+ES(pname(P))+'. காரணங்கள்:')+'</p><ul class="ak-ol">';
    (res.steps||[]).slice(0,9).forEach(s=>{ h+='<li>'+(s.ok===true?'✓ ':s.ok===false?'✗ ':'• ')+String(s.t||'')+'</li>'; });
    h+='</ul>';
    if(res.T&&res.T.length===undefined){}
    const chips=[]; const body=document.createElement('div'); body.innerHTML=stripIds($('hqOut').innerHTML); body.querySelectorAll('#hqmBox,[data-x="hqmBox"],.btns,button').forEach(x=>{ if(x.parentNode)x.parentNode.removeChild(x); });
    h+='<details class="ak-det"><summary>'+ES(L('Show the full horary chart, the timing of the event and the details','முழு பிரசன்ன ஜாதகம், நிகழ்வு நேரம், விவரங்கள்'))+'</summary><div class="ak-full">'+body.innerHTML+'</div></details>';
    const tp=topicOf(text||q.en);
    if(/^(exam|profexam|basicedu)$/.test(qid))chips.push([L('Ask for the exam date and give me a muhurtham','தேர்வு தேதியைக் கேட்டு முகூர்த்தம் தா'),()=>examDate()]);
    chips.push([L('Find the best time for this question to succeed','இந்தக் கேள்வி வெற்றி பெற சிறந்த நேரம் காண்'),()=>hqmForm(qid)]);
    if(tp&&tp[4])chips.push([L('Find a muhurtham for this','இதற்கு முகூர்த்தம் காண்'),()=>muhurtham(tp[4],'')]);
    if(tp)chips.push([L('Add my birth chart to this answer','இதற்கு என் ஜாதகத்தையும் சேர்'),()=>natalFlow(tp)]);
    const b=add('b',h,chips);
    if(!multi&&/^(foreign|passport|marry|child|job|govjob|buyprop|finstat|promote)$/.test(qid)&&tp){ if(S.prof){ setTimeout(()=>natalFlow(tp),50); } else needBirth(()=>natalFlow(tp),L('For a fuller prediction I also need your birth details.','முழுமையான பலனுக்கு உங்கள் பிறப்பு விவரங்களும் தேவை.')); }
  }
  /* ---------------- dates ---------------- */
  const MON={jan:0,january:0,feb:1,february:1,mar:2,march:2,apr:3,april:3,may:4,jun:5,june:5,jul:6,july:6,aug:7,august:7,sep:8,sept:8,september:8,oct:9,october:9,nov:10,november:10,dec:11,december:11,'ஜனவரி':0,'பிப்ரவரி':1,'மார்ச்':2,'ஏப்ரல்':3,'மே':4,'ஜூன்':5,'ஜூலை':6,'ஆகஸ்ட்':7,'செப்டம்பர்':8,'அக்டோபர்':9,'நவம்பர்':10,'டிசம்பர்':11};
  const iso=ms=>{ const d=new Date(ms); return d.getUTCFullYear()+'-'+P2(d.getUTCMonth()+1)+'-'+P2(d.getUTCDate()); };
  function todayLocal(){ const P=curPlace(); return Date.now()+offOf(P.tz,Date.now())*3600000; }
  function mkDate(d,mon,y,base){ if(y==null){ y=new Date(base).getUTCFullYear(); const c=Date.UTC(y,mon,d); if(c<base-70*DAY)y++; } return Date.UTC(y,mon,d); }
  function parseRange(t){
    const s=t.toLowerCase(), base=todayLocal();
    let m=s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{4})\s*(?:to|-|–|till|until|and)\s*(\d{1,2})[\/.](\d{1,2})[\/.](\d{4})/); if(m)return [Date.UTC(+m[3],+m[2]-1,+m[1]),Date.UTC(+m[6],+m[5]-1,+m[4])];
    m=s.match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{4})/); if(m){ const a=Date.UTC(+m[3],+m[2]-1,+m[1]); return [a,a]; }
    m=s.match(/(\d{4})-(\d{2})-(\d{2})\s*(?:to|-|–|till|until|and)\s*(\d{4})-(\d{2})-(\d{2})/); if(m)return [Date.UTC(+m[1],+m[2]-1,+m[3]),Date.UTC(+m[4],+m[5]-1,+m[6])];
    const mn='('+Object.keys(MON).filter(k=>/^[a-z]+$/.test(k)).join('|')+'|[஀-௿]+)';
    m=s.match(new RegExp('(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s*(?:of\\s*)?'+mn+'?\\s*,?\\s*(\\d{4})?\\s*(?:to|-|–|till|until|and|through)\\s*(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s*(?:of\\s*)?'+mn+'\\s*,?\\s*(\\d{4})?'));
    if(m&&MON[m[5]]!==undefined){ const m2=MON[m[5]], m1=(m[2]&&MON[m[2]]!==undefined)?MON[m[2]]:m2; const y2=m[6]?+m[6]:null, y1=m[3]?+m[3]:null; let a=mkDate(+m[1],m1,y1,base), b=mkDate(+m[4],m2,y2==null?(y1!=null?y1:null):y2,base); if(b<a)b=Date.UTC(new Date(b).getUTCFullYear()+1,m2,+m[4]); return [a,b]; }
    m=s.match(new RegExp('(?:on\\s+)?(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s*(?:of\\s*)?'+mn+'\\s*,?\\s*(\\d{4})?')); if(m&&MON[m[2]]!==undefined){ const a=mkDate(+m[1],MON[m[2]],m[3]?+m[3]:null,base); return [a,a]; }
    m=s.match(/next\s+(\d+)\s*(day|week|month|year)/)||s.match(/(?:coming|for|in)\s+(\d+)\s*(day|week|month|year)/); if(m){ const n=+m[1], k={day:1,week:7,month:30,year:365}[m[2]]; return [base,base+n*k*DAY]; }
    m=s.match(/(\d+)\s*(?:மாத|நாள்|வாரம்)/); if(m){ const k=/மாத/.test(s)?30:/வார/.test(s)?7:1; return [base,base+(+m[1])*k*DAY]; }
    if(/next\s+month|அடுத்த\s*மாதம்/.test(s)){ const d=new Date(base); return [Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1),Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+2,0)]; }
    if(/this\s+month|இந்த\s*மாதம்/.test(s)){ const d=new Date(base); return [base,Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)]; }
    if(/next\s+week|அடுத்த\s*வாரம்/.test(s))return [base+DAY,base+8*DAY];
    if(/this\s+week|இந்த\s*வாரம்/.test(s))return [base,base+6*DAY];
    if(/tomorrow|நாளை/.test(s))return [base+DAY,base+DAY];
    if(/today|இன்று/.test(s))return [base,base];
    if(/next\s+year|அடுத்த\s*ஆண்டு/.test(s)){ const y=new Date(base).getUTCFullYear()+1; return [Date.UTC(y,0,1),Date.UTC(y,11,31)]; }
    return null;
  }
  function askDates(title,def,max,cb){
    const b0=todayLocal(), a=def?def[0]:b0, z=def?def[1]:b0+6*DAY;
    const m=add('b','<p>'+title+'</p><div class="ak-row"><label>'+ES(L('From','முதல்'))+'<input type="date" class="ak-d1" value="'+iso(a)+'"></label><label>'+ES(L('To','வரை'))+'<input type="date" class="ak-d2" value="'+iso(z)+'"></label><button type="button" class="primary ak-dg">OK</button></div><div class="msg ak-dm"></div>');
    m.querySelector('.ak-dg').addEventListener('click',()=>{ const f=m.querySelector('.ak-d1').value, t=m.querySelector('.ak-d2').value, ms=m.querySelector('.ak-dm'); if(!f||!t){ ms.textContent=L('Choose both dates.','இரு தேதிகளையும் தேர்ந்தெடுங்கள்.'); return; } const nd=Math.round((Date.parse(t)-Date.parse(f))/DAY)+1; if(nd<1){ ms.textContent=L('The last date must not be before the first.','கடைசித் தேதி முதல் தேதிக்கு முன் இருக்கக் கூடாது.'); return; } if(nd>max){ ms.textContent=LT('Please choose at most {0} days here.',[max],'இங்கு அதிகபட்சம் '+max+' நாட்கள் மட்டும்.'); return; } m.querySelectorAll('input,button').forEach(x=>{ x.disabled=true; }); cb(f,t); });
  }
